package br.com.tapeteskalke.controller; import br.com.tapeteskalke.dto.*; import br.com.tapeteskalke.dto.UsuarioDtos.*; import br.com.tapeteskalke.service.UsuarioService; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/usuarios") public class UsuarioController { private final UsuarioService service; public UsuarioController(UsuarioService service){this.service=service;} @GetMapping public ApiResponse<List<Response>> list(){return ApiResponse.ok(service.list());} @PostMapping public ResponseEntity<ApiResponse<Response>> create(@Valid @RequestBody CreateRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(service.create(r)));} @PutMapping("/{id}") public ApiResponse<Response> update(@PathVariable String id,@Valid @RequestBody UpdateRequest r){return ApiResponse.ok(service.update(id,r));} @PutMapping("/{id}/senha") public ResponseEntity<Void> resetSenha(@PathVariable String id,@Valid @RequestBody ResetSenhaRequest r){service.resetSenha(id,r);return ResponseEntity.noContent().build();} }
